float rand(vec2 st)
{
    return fract(sin(dot(st, vec2(12.9898, 73.3454))) * 438474.0);
}

float noise_2d(vec2 st)
{
    vec2 i = floor(st);
    vec2 f = fract(st);

    //taking random value from points on a init rect
    float a = rand(i + vec2(0.0, 0.0));
    float b = rand(i + vec2(1.0, 0.0));
    float c = rand(i + vec2(0.0, 1.0));
    float d = rand(i + vec2(1.0, 1.0));

    //Hermite curve interpolation instead of smoothstep because i am a cool kid :)
    vec2 u = f * f * (3.0 - 2.0 * f);
    // u = smoothstep(0.0, 1.0, f);

    return mix(a, b, u.x) + (c - a) * u.y * (1.0 - u.x) + (d - b) * u.x * u.y;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord / iResolution.xy;
    uv *= 10.0;

    vec3 color = vec3(noise_2d(uv + vec2(iTime,0.0)));
    float value = sin(noise_2d(uv)*10.0+uv.x*5.0+2.0*iTime);

    color = mix(vec3(1.0, 0.2, 0.0), vec3(1.0, 0.8, 0.2), value);;
    // Output to screen
    fragColor = vec4(color, 1.0);
}
